(function(root){
 'use strict';
 const D=root.CM_DATA,E=root.CM_ENGINE,doc=root.document,$=id=>doc.getElementById(id);
 const lang=()=>root.CM_I18N?.getLanguage?.()||'zh',w=(zh,en)=>lang()==='en'?en:zh,tr=s=>root.CM_I18N?.t(s)||String(s||'');
 const esc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const pair=p=>typeof p==='object'&&p?(p[lang()]||p.zh||''):String(p||'');
 const fmt=n=>String(Math.floor(Math.max(0,n)/60)).padStart(2,'0')+':'+String(Math.floor(Math.max(0,n)%60)).padStart(2,'0');
 const card=id=>D.cards.find(c=>c.id===id),plot=id=>D.plots.find(p=>p.id===id),resident=id=>D.residents.find(r=>r.id===id);
 const rotations=id=>card(id)?.allowedRotations?.length?card(id).allowedRotations:[0,Math.PI/2,Math.PI,Math.PI*1.5];
 function nextRotation(id,current){const allowed=rotations(id),index=allowed.findIndex(value=>Math.abs(value-current)<.001);return allowed[(index+1)%allowed.length];}
 const rotationStep=id=>Math.round(((rotations(id)[1]||Math.PI*2)-rotations(id)[0])*180/Math.PI);
 const cardText=(c,key)=>lang()==='en'&&c?.[key+'En']?c[key+'En']:tr(c?.[key]);
 const plotText=(p,key)=>lang()==='en'&&p?.[key+'En']?p[key+'En']:tr(p?.[key]);
 const portrait=id=>(root.CM_ART?.portrait?.(id)||'').replace(/aria-label="([^"]*)"/g,(_,label)=>'aria-label="'+esc(tr(label))+'"'),scene=(kind,opts={})=>root.CM_VISUAL?.scene?.(kind,Object.assign({label:w('像素社区情境','Pixel neighbourhood scene')},opts))||'';
 const groupName=id=>tr(D.groups[id]),goalName=id=>({stay:w('住得下','Room to stay'),social:w('处得来','Community ties'),comfort:w('住得舒服','Liveability')})[id]||id;
 const status=value=>value>=68?{word:w('状态稳定','Stable'),cls:''}:value>=40?{word:w('仍需支持','Needs support'),cls:'amber'}:{word:w('居住受到影响','Home life affected'),cls:'red'};
 let state=E.create(),saved=null,inGame=false,speed=1,userPaused=false,selecting=null,selectedPlot=null,placement={x:0,z:0,rotation:0},landVisible=false;
 let modalView=null,contextIssue=null,filters={search:'',category:'all',goal:'all',available:false},quietSlot='afternoon',practice=false,tutorialStep=-1,tutorialCard='cover',tutorialPlace=null,tutorialRotation=0,tutorialFeedback='';
 let lastTick=root.performance.now(),lastPaint=0,saveClock=0,lastSerial=0,feedbackQueue=[],shownOutcome=false,lastPauseReason=null,noticeId=null;
 let lastMailCount=0,lastPrivateWarning='',toastTimer,bannerTimer,resourceReady=false,metricsReady=false,lastWorld='',lastHand='',lastNeighbours='';
 const seenNotices=new Set(),resourceValues={},resourceAnimations={},attributeSources=new WeakMap();
 try{const value=JSON.parse(root.localStorage.getItem('downstairs-clementi-v1'));if(value?.state?.groups&&Array.isArray(value.state.issues)&&!value.state.outcome)saved=E.migrate(value.state);}catch{}
 const button=(action,label,id='',cls='secondary-button',extra='')=>'<button class="'+cls+'" data-action="'+action+'"'+(id?' data-id="'+esc(id)+'"':'')+' '+extra+'>'+label+'</button>';
 function localizeStatic(){doc.querySelectorAll?.('[data-zh][data-en]').forEach(el=>{el.textContent=el.dataset[lang()==='en'?'en':'zh'];});doc.querySelectorAll?.('[aria-label],[title]').forEach(el=>{if(el.closest?.('[data-i18n-ignore]'))return;const saved=attributeSources.get(el)||{};for(const key of ['aria-label','title']){if(!el.hasAttribute?.(key))continue;const current=el.getAttribute(key),previous=saved[key],source=previous&&previous.rendered===current?previous.source:current,rendered=tr(source);if(current!==rendered)el.setAttribute(key,rendered);saved[key]={source,rendered};}attributeSources.set(el,saved);});if(doc.documentElement)doc.documentElement.lang=lang()==='en'?'en':'zh-CN';doc.title=w('Downstairs · 金文泰','Downstairs · Clementi');}
 function save(){if(!inGame)return;saved=state;try{root.localStorage.setItem('downstairs-clementi-v1',JSON.stringify({schema:2,state}));}catch{}}
 function pauseReason(){if(!inGame||root.CM_FLOW?.isActive?.())return w('选择社区中','Choosing a neighbourhood');if(state.outcome)return w('本局已结束，可回看社区','Game complete · review your neighbourhood');if(selecting)return w('选址中，社区时间已暂停','Placing a facility · time paused');if($('modal').open)return w('阅读或互动中，社区时间已暂停','Reading or interacting · time paused');if(userPaused)return w('你已暂停社区时间','You paused the neighbourhood');if(doc.hidden)return w('页面在后台，时间已暂停','Page in background · time paused');return '';}
 const blocked=()=>!!pauseReason();
 function toast(message){const el=$('toast');el.textContent=tr(message);el.hidden=false;el.classList.add('show');root.clearTimeout(toastTimer);toastTimer=root.setTimeout(()=>{el.hidden=true;el.classList.remove('show');},3600);}
 function open(title,body,eyebrow=w('楼下 · 金文泰','Downstairs · Clementi'),wide=false,view=null){modalView=view;const modal=$('modal');modal.classList.toggle('library-modal',wide);$('modal-content').innerHTML='<div class="modal-top"><div><div class="eyebrow">'+esc(eyebrow)+' · Ⅱ '+w('时间已暂停','Time paused')+'</div><h2 id="modal-title">'+esc(title)+'</h2></div>'+button('close','×','','close','aria-label="'+w('关闭','Close')+'"')+'</div><div class="modal-body">'+body+'</div>';if(!modal.open)modal.showModal();renderTime();}
 function close(){modalView=null;$('modal').close();lastTick=root.performance.now();renderTime();}
 function details(summary,body){return '<details><summary>'+summary+'</summary><div class="detail-prose">'+body+'</div></details>';}
 function setNotice(html){const el=$('event-notice');el.innerHTML=html;el.hidden=!html;}
 function renderTime(){const reason=pauseReason(),paused=!!reason;$('clock').textContent=(paused?w('暂停 ','Paused '):w('经营 ','Running '))+fmt(state.time);$('pause').textContent=userPaused?'▶':'Ⅱ';$('pause').setAttribute('aria-label',userPaused?w('继续经营','Resume'):w('暂停经营','Pause'));$('pause').title=reason||w('社区时间正在流逝','Neighbourhood time is passing');$('speed').textContent=speed+'×';$('language-toggle').textContent=lang()==='en'?'中文':'English';const el=$('time-state');el.textContent=reason||w('▶ 时间流逝中 · 未回应的问题会恶化','▶ Time is passing · unanswered issues can worsen');el.classList.toggle('running',!paused);if(inGame&&lastPauseReason!==reason){const b=$('time-banner');b.innerHTML=esc(reason||w('社区时间继续','Neighbourhood time resumes'))+'<small>'+w('阅读与选址自动暂停；回到社区后继续。','Reading and placement pause time; return to the world to continue.')+'</small>';b.hidden=false;root.clearTimeout(bannerTimer);bannerTimer=root.setTimeout(()=>{b.hidden=true;},2000);}lastPauseReason=reason;const svg=$('world')?.querySelector?.('svg');if(svg){if(paused)svg.pauseAnimations?.();else svg.unpauseAnimations?.();}}
 function ensureResources(){if(resourceReady)return;resourceReady=true;$('resources').innerHTML=['budget','trust','staffUsed'].map((id,i)=>'<div class="resource" id="resource-'+id+'"><small id="resource-label-'+id+'"></small><strong><span class="resource-glyph">'+['◈','♡','♧'][i]+'</span><span id="resource-value-'+id+'"></span></strong><em id="resource-note-'+id+'"></em></div>').join('');}
 function renderResources(){ensureResources();const values={budget:Math.floor(state.budget),trust:Math.round(state.trust),staffUsed:state.staffUsed};for(const id of Object.keys(values)){const label=id==='budget'?w('预算','Budget'):id==='trust'?w('居民信任','Resident trust'):w('运营人手','Service staff');$('resource-label-'+id).textContent=label;$('resource-note-'+id).textContent=id==='budget'?w('随时间恢复','Recovers over time'):id==='trust'?w('居民对管理者','Residents → manager'):w('已占用 / 共6人','Assigned / 6 total');if(!resourceAnimations[id]){$('resource-value-'+id).textContent=id==='staffUsed'?values[id]+' / '+state.staffTotal:String(values[id]);resourceValues[id]=values[id];}}}
 function animateResource(id,delta){if(!delta)return;ensureResources();const container=$('resource-'+id),value=$('resource-value-'+id),target=id==='budget'?Math.floor(state.budget):id==='trust'?Math.round(state.trust):state.staffUsed,from=resourceValues[id]??(target-delta);resourceValues[id]=target;container.classList.remove('is-changing');void container.offsetWidth;container.classList.add('is-changing');const floating=doc.createElement('span');floating.className='resource-delta'+(delta<0?' negative':'');floating.textContent=(delta>0?'+':'')+delta+(id==='staffUsed'?w(' 占用',' assigned'):'');container.appendChild?.(floating);root.setTimeout(()=>floating.remove?.(),1550);if(!root.requestAnimationFrame){value.textContent=id==='staffUsed'?target+' / '+state.staffTotal:String(target);return;}const start=root.performance.now(),token={};resourceAnimations[id]=token;function frame(now){if(resourceAnimations[id]!==token)return;const progress=Math.min(1,(now-start)/600),n=Math.round(from+(target-from)*(1-Math.pow(1-progress,3)));value.textContent=id==='staffUsed'?n+' / '+state.staffTotal:String(n);if(progress<1)root.requestAnimationFrame(frame);else delete resourceAnimations[id];}root.requestAnimationFrame(frame);}
 function sceneKind(id){return String(id||'').replace(/^action-/,'');}
 function availability(c){if(c.land?.length){const checks=c.land.map(id=>E.available(state,c.id,id));return checks.find(r=>r.ok)||checks[0];}return E.available(state,c.id);}
 function feeText(c){return '◈ '+c.budget+(c.trustCost?' · ♡ −'+c.trustCost:'')+(c.staff?' · ♧ '+c.staff:'')+' · ◷ '+(c.duration?c.duration+'s':w('即时','now'));}
 function cardMarkup(c,recommended=false){const a=availability(c),title=cardText(c,'title');let art='';try{art=(root.CM_ART?.facility(c.id)||'').replace(/aria-label="([^"]*)"/g,(_,label)=>'aria-label="'+esc(tr(label))+'"');}catch{}if(!art||c.actionOption)art=scene(sceneKind(c.id),{complete:false});return '<button class="play-card '+(a.ok?'':'unavailable')+'" data-action="card" data-id="'+esc(c.id)+'"><span class="card-pip">'+c.budget+'</span><span class="card-category">'+tr(c.type)+(recommended?' · '+w('与当前处境有关','Related to this situation'):'')+'</span><div class="card-art">'+art+'</div><h3>'+esc(title)+'</h3><span class="card-fees">'+esc(feeText(c))+'</span><span class="card-status">'+(a.ok?w('可以探索这项安排','Explore this action'):esc(tr(a.message)))+'</span></button>';}
 function recommendedCards(issueId){const i=state.issues.find(i=>i.id===issueId);if(!i)return [];const ids=[];for(const o of i.options||[]){if(o.id==='build')ids.push('nrp');else if(o.id==='corner'&&issueId==='stall'&&state.flags.completed.corner)ids.push('action-corner');else if(card(o.id))ids.push(o.id);else if(card('action-'+o.id))ids.push('action-'+o.id);}return [...new Set(ids)];}
 function filteredCards(){const recommended=recommendedCards(contextIssue);return D.cards.filter(c=>(filters.category==='all'||c.type===filters.category)&&(filters.goal==='all'||(c.goals||[]).includes(filters.goal))&&(!filters.available||availability(c).ok)&&(!filters.search||(cardText(c,'title')+' '+cardText(c,'desc')).toLowerCase().includes(filters.search.toLowerCase()))).sort((a,b)=>Number(recommended.includes(b.id))-Number(recommended.includes(a.id)));}
 function libraryGrid(){const list=filteredCards(),recommended=recommendedCards(contextIssue);return list.length?list.map(c=>cardMarkup(c,recommended.includes(c.id))).join(''):'<p class="empty-copy">'+w('没有符合筛选的卡牌。试试其他类别或清空搜索。','No cards match. Try another category or clear the search.')+'</p>';}
 function showLibrary(issueId){if(typeof issueId==='string')contextIssue=issueId;const context=state.issues.find(i=>i.id===contextIssue);open(w('你的完整行动牌库','Your complete action library'),'<p class="library-description">'+(context?w('刚才观察：','You just observed: ')+esc(tr(context.title))+' · ':'')+w('相关牌排在前面，你仍可查看全部行动。','Related cards appear first. Every action remains available to explore.')+'</p><div class="library-tools"><input id="library-search" type="search" placeholder="'+w('搜索卡牌或用途','Search cards or uses')+'" aria-label="'+w('搜索卡牌','Search cards')+'" value="'+esc(filters.search)+'"><div class="filter-buttons">'+[['all',w('全部','All')],['设施',w('设施','Facilities')],['政策',w('政策','Policies')],['服务',w('服务','Services')],['活动',w('活动','Activities')]].map(([id,label])=>button('category',label,id,filters.category===id?'active':'')).join('')+'</div></div><div class="filter-buttons">'+[['all',w('所有目标','All goals')],['stay',goalName('stay')],['social',goalName('social')],['comfort',goalName('comfort')]].map(([id,label])=>button('goal-filter',label,id,filters.goal===id?'active':'')).join('')+button('available-filter',w('仅看当前可用','Available now'),'',filters.available?'active':'')+'</div><div class="library-grid" id="library-grid">'+libraryGrid()+'</div>',w('自由探索 · 看牌时暂停','Explore freely · time paused'),true,{kind:'library'});}
 function renderLibraryGrid(){const el=$('library-grid');if(el)el.innerHTML=libraryGrid();}
 function costIcons(c){return '<div class="cost-icons"><div><small>◈ '+w('预算','Budget')+'</small><strong>'+c.budget+'</strong></div><div><small>♡ '+w('信任消耗','Trust cost')+'</small><strong>'+(c.trustCost||0)+'</strong></div><div><small>♧ '+w('运营人手','Service staff')+'</small><strong>'+c.staff+' '+(c.staffMode==='temporary'?w('临时','temporary'):c.staffMode==='ongoing'?w('持续','ongoing'):w('无需占用','unassigned'))+'</strong></div><div><small>◷ '+w('工期／准备','Time to prepare')+'</small><strong>'+(c.duration?c.duration+' '+w('秒','seconds'):w('即时','Immediate'))+'</strong></div></div>';}
 function changesMarkup(changes){if(!changes)return '';const labels={budget:w('预算','Budget'),trust:w('居民信任','Trust'),staffUsed:w('人手占用','Staff assigned'),social:goalName('social'),comfort:goalName('comfort'),stay:goalName('stay')};const entries=Object.entries(labels).filter(([id])=>changes[id]).map(([id,label])=>'<span class="'+(changes[id]<0?'negative':'')+'">'+label+' '+(changes[id]>0?'+':'')+changes[id]+'</span>');for(const [id,n]of Object.entries(changes.groups||{}))if(n)entries.push('<span class="'+(n<0?'negative':'')+'">'+groupName(id)+' '+(n>0?'+':'')+n+'</span>');return '<div class="result-deltas">'+entries.join('')+'</div>';}
 function showCard(id){const c=card(id);if(!c)return;const a=availability(c),context=c.actionOption?E.actionContext(state,c):null;const goals=(c.goals||[]).map(id=>'<span class="goal-chip">△ '+goalName(id)+'</span>').join('');open(cardText(c,'title'),'<div class="scene-and-dialogue">'+scene(sceneKind(id),{complete:!!state.flags.completed[id]})+'<div><div class="speaker">'+(c.actionOption?w('邻里行动','Neighbourhood action'):tr(c.type))+'</div><p class="persona-intro">'+esc(cardText(c,'desc'))+'</p><div class="goal-chips">'+goals+'</div></div></div>'+costIcons(c)+'<p class="library-description">'+esc(cardText(c,'effects'))+'</p>'+(context?'<p class="library-description">'+w('回应当前处境：','Responds to: ')+esc(tr(context.title))+'</p>':'')+(!a.ok?'<div class="availability-note">'+esc(tr(a.message))+'</div>':'')+'<div class="modal-bottom">'+button('use-card',c.land?.length?w('拿起这张牌，去选位置','Pick up card and choose a place'):c.actionOption==='mediate'?w('进入作息调解','Begin the quiet-hours meeting'):w('安排这项行动','Arrange this action'),id,'primary-button',a.ok?'':'disabled')+button('library',w('返回全部牌库','Back to all cards'))+'</div>'+details(w('现实对照与完整说明','Real-world context and details'),'<p>'+esc(tr(c.source?.text||''))+'</p>'+(c.source?.url?'<a href="'+esc(c.source.url)+'" target="_blank" rel="noopener noreferrer">'+esc(tr(c.source.title))+' ↗</a>':'')+'<p>'+w('卡牌数值与候选位置为游戏设定。施工队包含在工程费用中，运营人手另计。','Card values and candidate sites are game assumptions. Construction crews are included in engineering costs; service staff are counted separately.')+'</p>'),w('行动卡 · 阅读时暂停','Action card · time paused'),false,{kind:'card',id});}
 function useCard(id){const c=card(id);if(!c)return;if(c.actionOption==='mediate'){showMediation();return;}if(c.land?.length){selecting=id;selectedPlot=null;placement={x:0,z:0,rotation:0};close();renderPlacement();root.HDBScene?.clearPreview?.();render();toast(w('选择一处描边的适用位置；选址期间时间暂停。','Choose an outlined suitable place. Time pauses during placement.'));return;}execute(id);}
 function execute(id,plotId,position){const result=E.play(state,id,plotId,position);if(!result.ok){toast(result.message);return false;}selecting=null;selectedPlot=null;root.HDBScene?.clearPreview?.();$('placement-panel').hidden=true;close();save();consumeEvents();render();flushFeedback();return true;}
 function showPlot(id){const p=plot(id);if(!p)return;selectedPlot=id;if(selecting){placement={x:0,z:0,rotation:0};renderPlacement();root.HDBScene?.previewPlacement?.(id,selecting,placement);render();return;}const built=state.plots[id],c=card(built?.cardId),candidates=D.cards.filter(c=>c.land?.includes(id));open(plotText(p,'name'),'<div class="scene-and-dialogue">'+scene(c?.id||p.kind,{complete:built?.status==='complete'})+'<div><p class="persona-intro">'+esc(plotText(p,'description'))+'</p><div class="impact-tags"><span>'+esc(built?.status==='complete'?w('已使用','In use'):built?.status==='building'?w('施工中','Under construction'):p.kind==='locked'?w('已有用途，不能建设','Existing use · no building'):w('可以查看适用行动','Explore suitable actions'))+'</span></div></div></div>'+(c?'<p>'+esc(cardText(c,'title'))+(built.status==='building'?' · '+Math.ceil(built.remaining)+'s':'')+'</p>':'')+'<div class="modal-bottom">'+candidates.map(c=>button('card',esc(cardText(c,'title')),c.id)).join('')+'</div><p class="new-epoch">'+w('位置为示意，未核实为金文泰真实可开发地块。','Illustrative sites, not verified developable land in Clementi.')+'</p>',w('社区空间','Neighbourhood space'),false,{kind:'plot',id});}
 function renderPlacement(){const el=$('placement-panel');if(!selecting){el.hidden=true;return;}if(!selectedPlot){const held=card(selecting);el.hidden=false;el.innerHTML='<h3>'+esc(cardText(held,'title'))+'</h3><p>'+w('手中有一张设施牌。点击社区中描边的位置，查看是否合适；你可以旋转镜头寻找。','You are holding a facility card. Select an outlined place to explore its suitability; rotate the camera to look around.')+'</p><p>'+esc(feeText(held))+' · '+w('尚未扣费，时间已暂停','Not charged yet · time paused')+'</p><div class="modal-bottom">'+button('cancel-select',w('放回卡牌','Put card back'))+'</div>';return;}const c=card(selecting),p=plot(selectedPlot),size=p.sceneSize||[6,6],limitX=Math.min(1,size[0]/5),limitZ=Math.min(1,size[1]/5),a=E.available(state,c.id,p.id,placement);el.hidden=false;el.innerHTML='<h3>'+esc(cardText(c,'title'))+' · '+esc(plotText(p,'name'))+'</h3><p>'+esc(plotText(p,'coverage')||plotText(p,'description'))+'</p><p>'+w('拖动微调位置，旋转朝向；预算与工期确认后才开始。','Adjust position and orientation. Costs and construction begin only after confirmation.')+'</p><div class="placement-tools"><label>'+w('横向','Across')+' <input id="placement-x" type="range" min="'+(-limitX)+'" max="'+limitX+'" step="0.1" value="'+placement.x+'"></label><label>'+w('纵向','Along')+' <input id="placement-z" type="range" min="'+(-limitZ)+'" max="'+limitZ+'" step="0.1" value="'+placement.z+'"></label>'+button('rotate-placement','↻ '+rotationStep(c.id)+'°')+'</div><p>'+esc(feeText(c))+' · '+(a.ok?w('可以放置','Ready to place'):esc(tr(a.message)))+'</p><div class="modal-bottom">'+button('confirm-placement',w('确认在这里安排','Confirm this location'),'','primary-button',a.ok?'':'disabled')+button('cancel-select',w('放回卡牌','Put card back'))+'</div>';}
 const issueCopy={
  route:['陈玉英','家里还是熟悉的，只是雨天不敢走这段露天路。','Home is familiar. It is this uncovered walk that keeps me in when it rains.','长者出行与居住环境会因持续等待受到影响。','Waiting can affect older residents’ access and neighbourhood liveability.'],
  noise:['学生 / 陈玉英 / 阿丽','我们住在同一栋楼，却还不了解彼此的休息时间。','We share one block, but do not yet understand each other’s rest times.','持续冲突会影响邻里关系与租户的居住稳定。','Ongoing conflict affects community ties and tenants’ stability.'],
  housing:['拉赫曼与努尔','孩子搬出去了，我们想知道换房接下来能找谁帮忙。','Our children have moved out. Who can help us with the next housing step?','一直没有进展，会影响换房屋主的状态与信任。','A lack of progress can affect owners looking to move and their trust.'],
  waiting:['拉赫曼与努尔','多一点时间有帮助，但我们还需要具体的下一步。','More time helps, but we still need a concrete next step.','继续等待会影响换房屋主的状态。','Further waiting can affect the household’s stability.'],
  care:['德薇','我们轮流请假照顾母亲，也想知道有哪些可靠的支持。','We take turns taking leave to care for Mum. What reliable support can we find?','照护家庭的压力会随等待增加。','Pressure on caregiving households can grow while they wait.'],
  carealt:['德薇','没有新公寓，我们也想知道怎样在原来的家继续生活。','Without a new apartment, how can we keep living in our existing home?','照护需求仍需要具体安排。','Care needs still require practical arrangements.'],
  land:['林家 / 照护家庭','同一片花园，承载了不同家庭的期待。','The same garden holds different households’ hopes.','拖延不会消除两种需求；任何建设也会改变原有空间。','Waiting does not remove either need. Building changes the existing shared space.'],
  childcare:['林家','我们理解关怀住房的重要，孩子的日常也需要安排。','We understand the need for care housing. Our children’s days still need support.','未得到支持的年轻家庭仍会承受压力。','Young families without support continue to face pressure.'],
  help:['学生 / 陈玉英','顺路帮忙可以，但我们先约好适合彼此的时间吧。','Helping along the way sounds good. Let us agree on a time that suits everyone.','这次相识需要后续联系，才能成为日常互助。','An introduction needs follow-up to become everyday help.'],
  rumor:['张叔','有人对个案帮助有疑问，我们先向当事人核实。','Some neighbours have questions about the case. Let us check with the people involved.','没有沟通，疑问会影响邻里关系与信任。','Without communication, questions can affect relationships and trust.'],
  stall:['黄美兰','我还想见熟客，也希望每周能多休息一天。','I still want to see my regulars, and would like one more day of rest each week.','相聚的地方需要继续，也要尊重摊主的休息。','Keep places to meet while respecting the stallholder’s need for rest.'],
  petition:['张叔','旧公共区域需要更新，先让合资格屋主表达意见。','Our shared areas need attention. Let eligible owners have their say.','更新支持率需要独立征集，不能用信任代替。','Renewal support needs a separate vote; trust does not replace it.'],
  ballot:['合资格屋主','我们想了解工程，也想知道施工会怎样影响日常。','We want to understand the works and how construction will affect daily life.','达到75%支持率，才可以启动这项更新。','This renewal needs at least 75% support before it starts.'],
  foodreturn:['黄美兰 / 陈玉英','熟悉的路又通了，食阁的那个位子又有人了。','The familiar route is open again, and the hawker-centre seat is occupied once more.','记录反馈，继续留意居民日常。','Record the feedback and keep paying attention to everyday life.']
 };
 function issueInfo(i){const c=issueCopy[i.id]||[i.person,i.body,i.body,'',''];return{speaker:tr(c[0]),quote:lang()==='en'?c[2]:c[1],impact:lang()==='en'?c[4]:c[3]};}
 function showIssue(id){const i=state.issues.find(i=>i.id===id);if(!i)return;contextIssue=id;i.read=true;noticeId=null;seenNotices.add(id+':'+i.stage);setNotice('');if(i.channel==='world')root.HDBScene?.focusIssue?.(id);const info=issueInfo(i),privateMail=i.channel==='mail';const conversation='<div class="speaker">'+esc(info.speaker)+'</div><div class="'+(privateMail?'letter-paper-new':'speech-box')+'"><p>'+esc(info.quote)+'</p></div><div class="impact-tags"><span>'+esc(i.status==='pending'?w('正在跟进','In progress'):w('等待回应','Awaiting a response'))+'</span><span>'+w('已等待 ','Waiting ')+Math.floor(i.age)+'s</span></div>';open(tr(i.title),'<div class="scene-and-dialogue">'+scene(i.id,{complete:i.status==='resolved'})+'<div>'+conversation+'</div></div><p class="library-description">'+esc(info.impact)+'</p><p class="library-description">'+(i.status==='open'?w('需要回应的问题每等待约60秒会进一步变化。阅读时暂停；回到社区后继续计时。','Unanswered issues change after roughly every 60 seconds of waiting. Reading pauses time; returning to the world resumes it.'):w('已有安排，正在等待后续。你仍可以探索其他行动。','An arrangement is underway. You can still explore other actions.'))+'</p>'+(i.id==='ballot'&&state.vote?'<div class="impact-tags"><span>'+w('投票支持率 ','Voting support ')+state.vote.support+'% / 75%</span></div>':'')+'<div class="modal-bottom">'+button('library',w('打开完整牌库，自由寻找办法','Explore all action cards'),'','primary-button')+button('ideas',w('看看不同思路','Explore different approaches'),id)+button('close',w('回社区观察','Observe the neighbourhood'))+'</div>'+details(w('完整来信与背景','Full message and background'),'<p>'+esc(tr(i.body)).replace(/\n/g,'<br>')+'</p>'+( ['housing','waiting','rumor'].includes(id)?'<p>'+w('楼栋构成示意：华族70%、马来族22%、印度裔及其他8%。这是虚构演示数据，不是实际配额门槛或金文泰人口数据。','Illustrative block mix: Chinese 70%, Malay 22%, Indian and other households 8%. Fictional demonstration data, not real quota thresholds or Clementi population statistics.')+'</p>':'')),privateMail?w('居民来信 · 仅在邮箱中阅读','Resident letter · read in your mailbox'):w('社区观察 · 地图上正在发生','Neighbourhood observation · happening on the map'),false,{kind:'issue',id});save();renderMailbox();}
 function showIdeas(id){const i=state.issues.find(i=>i.id===id);if(!i)return;const ids=recommendedCards(id);open(w('可以从哪些方向想一想？','What approaches could you explore?'),'<p class="library-description">'+w('这些是参考，不是必须完成的三选一。你可以看完整牌库，也可以先回社区观察。','These are suggestions, not a compulsory multiple-choice question. Explore every card or return to observe.')+'</p><div class="idea-grid">'+ids.map(id=>{const c=card(id);return '<button class="idea-card" data-action="card" data-id="'+id+'">'+scene(sceneKind(id))+'<strong>'+esc(cardText(c,'title'))+'</strong><small>'+esc(cardText(c,'desc'))+'</small></button>';}).join('')+'</div><div class="modal-bottom">'+button('library',w('查看全部行动','See every action'),'','primary-button')+button('issue',w('回到刚才的处境','Back to the situation'),id)+'</div>',w('视觉参考 · 不自动执行','Visual suggestions · no action is executed'),true,{kind:'ideas',id});}
 function showInbox(){const mails=state.issues.filter(i=>i.channel==='mail').slice().reverse();open(w('居民邮箱','Resident mailbox'),'<p class="library-description">'+w('居民主动写给你的私人需求与后续反馈。地图观察在社区里另行查看。','Personal requests and follow-up messages written to you. Public observations appear in the neighbourhood.')+'</p><div class="mail-list">'+(mails.length?mails.map(i=>{const p=residentForIssue(i.id);return '<button class="mail-row" data-action="issue" data-id="'+i.id+'">'+portrait(p)+'<span><strong>'+esc(tr(i.title))+'</strong><small>'+esc(tr(i.person))+' · '+(i.status==='resolved'?w('已回应','Answered'):i.status==='pending'?w('跟进中','In progress'):Math.floor(i.age)+'s '+w('等待回应','waiting'))+'</small>'+(i.status==='open'&&i.age>=40?'<small style="display:block;color:#f4ba99">'+w('继续等待可能影响居民，请及时查看。','Further waiting can affect residents. Please read soon.')+'</small>':'')+'</span>'+(!i.read?'<i class="unread-dot"></i>':'')+'</button>';}).join(''):'<p class="empty-copy">'+w('暂时没有来信。你可以先到社区观察。','No letters yet. Take a look around the neighbourhood.')+'</p>')+'</div>',w('来信需主动打开阅读','Open a letter to read it'),false,{kind:'inbox'});}
 function residentForIssue(id){return({route:'chen',noise:'students',housing:'rahman',waiting:'rahman',help:'students',rumor:'zhang',care:'kumar',carealt:'kumar',land:'lin',childcare:'lin',stall:'huang',petition:'zhang',ballot:'zhang',foodreturn:'huang'})[id]||'chen';}
 function showResident(id){const r=resident(id),p=root.CM_COMMUNITY?.personas?.[id];if(!r)return;const st=status(state.groups[r.group]),related=state.issues.filter(i=>i.status!=='resolved'&&residentForIssue(i.id)===id);const identity=p?'<div class="identity-tags"><span>'+esc(p.ageRange?p.ageRange.join('–'):p.ages?p.ages.join(' / '):p.age)+' '+w('岁','years')+'</span><span>'+esc(pair(p.role))+'</span><span>'+esc(pair(p.tenure))+'</span></div><p>'+esc(pair(p.family))+'</p><p class="persona-intro">'+esc(pair(p.routine))+'</p>':'<p>'+esc(tr(r.role))+'</p>';open(tr(r.name),'<div class="scene-and-dialogue"><div class="identity-portrait">'+portrait(id)+'</div><div><div class="speaker">'+w('认识这位邻居','Meet your neighbour')+'</div>'+identity+'<div class="impact-tags"><span>'+groupName(r.group)+' · '+st.word+'</span></div></div></div><div class="modal-bottom">'+related.map(i=>button(i.channel==='mail'?'inbox':'issue',i.channel==='mail'?w('查看相关来信','Check their letters'):esc(tr(i.title)),i.channel==='world'?i.id:'')).join('')+button('close',w('回到社区','Back to the neighbourhood'))+'</div>'+details(w('认识的人与完整背景','Connections and background'),'<p>'+esc(tr(r.home))+'</p><ul>'+(r.relations||[]).map(s=>'<li>'+esc(tr(s))+'</li>').join('')+'</ul>')+details(w('角色创作依据','Character evidence'),'<p>'+esc(p?pair(p.evidence):w('居民为虚构人物。','This resident is fictional.'))+'</p><p>'+w('群体统计用于了解社区背景，不能证明个人的精确年龄、职业或经历。','Population statistics inform the context; they do not establish an individual’s exact age, occupation or story.')+'</p>'),w('邻居档案 · 虚构人物','Neighbour profile · fictional character'),false,{kind:'resident',id});}
 function showResidents(){open(w('住在这里的人','Your neighbours'),'<div class="library-grid">'+D.residents.map(r=>'<button class="mail-row" data-action="resident" data-id="'+r.id+'">'+portrait(r.id)+'<span><strong>'+esc(tr(r.name))+'</strong><small>'+esc(tr(r.role))+'</small></span></button>').join('')+'</div><p class="new-epoch">'+w('八户虚构人物，不是人口比例抽样。','Eight fictional households, not a proportional population sample.')+'</p>',w('点击一户，先了解一个人','Select a household and meet a neighbour'),true,{kind:'residents'});}
 function showMediation(){open(w('一起约定安静时段','Agree quiet hours together'),'<div class="scene-and-dialogue">'+scene('mediate',{people:['chen','students','ali']})+'<div><div class="speaker">'+w('陈玉英 · 学生 · 阿丽','Mdm Chen · Students · Ali')+'</div><div class="speech-box"><p>'+w('“我们先了解彼此的作息，再约一个适合交流的时间。”','“Let us understand each other’s routines, then agree on a time to meet.”')+'</p></div></div></div><div class="quiet-band"><span>'+w('长者休息','Older residents')+'</span><i></i></div><div class="quiet-band nurse"><span>'+w('轮班休息','Shift rest')+'</span><i></i></div><p class="library-description">'+w('选择一次共同见面的时段。安静约定也尊重轮班住户白天休息；具体时段是角色剧情设定。','Choose a meeting time. Quiet arrangements also respect daytime rest after shifts. These schedules are fictional story details.')+'</p><div class="quiet-slots">'+[['morning',w('上午','Morning')],['afternoon',w('下午','Afternoon')],['evening',w('傍晚','Early evening')]].map(([id,label])=>button('quiet-slot',label,id,quietSlot===id?'active':'')).join('')+'</div><div class="modal-bottom">'+button('confirm-mediate',w('确认见面并建立约定 · 信任−3','Meet and agree · trust −3'),'','primary-button')+button('library',w('再看看其他办法','Explore other actions'))+'</div>',w('互动情境 · 确认后才扣资源','Interactive scene · charged on confirmation'),false,{kind:'mediation'});}
 const ruleExamples={stay:['cover','appeal','visits'],social:['action-mediate','corner','event'],comfort:['cover','ramp','ease','nrp']};
 function showGoals(goal='stay'){if(!['stay','social','comfort'].includes(goal))goal='stay';const lines={stay:[w('让不同家庭有条件继续住在这里','Help different households continue living here'),w('了解谁正承受压力，再改善住房、出行或照护支持。帮助一类居民稳定下来，就能提高住得下。','Find out who is under pressure, then improve housing, access or care support. Stabilising a resident group improves room to stay.')],social:[w('让邻居有机会认识、协商与互助','Help neighbours meet, agree and support one another'),w('调解冲突、安排相遇空间和交流活动。居民彼此的联系属于处得来；对管理者的信任另算。','Mediate conflicts and create places and occasions to meet. Community ties describe neighbours’ relationships; trust in the manager is separate.')],comfort:[w('让每天走的路、住的家更便利','Make everyday routes and homes work better'),w('遮雨、无障碍与屋内安全处理的是不同困难。看清空间问题，安排对应改善。','Shelter, accessibility and home safety address different barriers. Observe the place and match the improvement to it.')]};const examples=ruleExamples[goal].map(card).filter(Boolean);open(w('三个目标，怎样做到？','Three goals: what can I do?'),'<p class="rule-first-intro">'+w('先看生活怎样改变，再探索相关行动。练习不会消耗正式资源。','See how daily life can change, then explore related actions. Practice costs no game resources.')+'</p><div class="rule-tabs">'+['stay','social','comfort'].map(id=>button('rule-tab',goalName(id),id,goal===id?'active':'')).join('')+'</div><div class="rule-example">'+scene(goal,{complete:practice})+'<div><h3>'+lines[goal][0]+'</h3><p>'+lines[goal][1]+'</p><div class="rule-action-list">'+examples.map(c=>button('card',esc(cardText(c,'title')),c.id)).join('')+'</div></div></div><div class="modal-bottom">'+button('practice',practice?w('再看改善前','See before again'):w('试一试：看看改善后','Try it: see the change'),goal,'primary-button')+button('library',w('探索全部行动','Explore all actions'))+'</div><div class="practice-feedback">'+(practice?w('练习结果：人物和环境出现改善，相关目标随之提高。正式预算没有变化。','Practice result: people and places improve, raising the related goal. Your real budget has not changed.'):'')+'</div>'+details(w('达标条件与精确规则','Completion conditions and exact rules'),'<p>'+w('住得下≥68、处得来≥70、住得舒服≥70，同时维持60经营秒即完成。任一目标低于25且危险状态持续45秒则结束。没有固定总倒计时。','Keep room to stay ≥68, community ties ≥70 and liveability ≥70 together for 60 game seconds to finish. If at least one goal remains below 25 for 45 seconds, the game ends. There is no fixed overall countdown.')+'</p><p>'+w('五类居民每稳定一类，住得下计20分；每类状态达到68才算稳定。因此实际至少四类稳定。投票支持率是另一项独立门槛。','Each of five stable resident groups contributes 20 points to room to stay. A group is stable at 68, so at least four groups must be stable. Voting support is a separate requirement.')+'</p>'),w('Rulebook · 可以做什么','Rulebook · actions you can take'),false,{kind:'goals',id:goal});}
 function showTutorial(step=-1){
  tutorialStep=step;const headings=[w('观察一个正在生活的社区','Observe a neighbourhood in motion'),w('拿起一张卡，探索能做什么','Pick up a card and explore'),w('把练习牌放在适合的位置','Place your practice card somewhere suitable')];
  if(step<0){tutorialCard='cover';tutorialPlace=null;tutorialRotation=0;tutorialFeedback='';open(w('先试一次，再自由探索','Try once, then explore freely'),'<div class="scene-and-dialogue">'+scene('tutorial')+'<div><h3>'+w('观察 → 找行动 → 看变化','Observe → choose an action → see the change')+'</h3><p>'+w('社区时间在主地图上流逝。阅读、练习和选址会暂停；未回应的问题会随等待产生影响。','Time passes in the main world. Reading, practice and placement pause it. Unanswered issues can affect residents as they wait.')+'</p></div></div><div class="modal-bottom">'+button('tutorial-step',w('开始短互动教程','Start the short tutorial'),'0','primary-button')+button('tutorial-skip',w('我想直接探索','Explore on my own'))+'</div>',w('可跳过，之后可从帮助重看','Skippable · replay from Help'),false,{kind:'tutorial',step:-1});return;}
  let content='',actions='';
  if(step===0){content=scene('tutorial')+'<p>'+w('陈玉英在露天路口停步。你先观察处境，再决定要探索什么行动。','Mdm Chen stops at the uncovered path. Observe the situation before deciding which action to explore.')+'</p>';actions=button('tutorial-step',w('我观察到了 → 打开练习牌库','I noticed it → open practice cards'),'1','primary-button');}
  if(step===1){content='<p>'+w('亲手拿起一张练习牌。三个方向解决不同困难，之后还可以在正式牌库探索更多行动。','Pick up a practice card. These approaches address different barriers; the real library offers many more actions.')+'</p><div class="idea-grid">'+['cover','ramp','ease'].map(id=>{const c=card(id);return '<button class="idea-card" data-action="tutorial-pick" data-id="'+id+'">'+scene(id)+'<strong>'+esc(cardText(c,'title'))+'</strong><small>'+esc(cardText(c,'desc'))+'</small></button>';}).join('')+'</div>';}
  if(step===2){const locations=[['route',w('露天步行段','Uncovered path'),'cover'],['crossing',w('入口与过街处','Entrance and crossing'),'ramp'],['home',w('屋内与入口','Inside the home'),'ease']],correct={cover:'route',ramp:'crossing',ease:'home'}[tutorialCard],valid=tutorialPlace===correct;
   content='<p>'+w('手中练习牌：','Practice card in hand: ')+esc(cardText(card(tutorialCard),'title'))+' · '+w('点击一个描边的位置。','Select an outlined place.')+'</p><div class="idea-grid">'+locations.map(([id,label,kind])=>'<button class="idea-card" style="border:2px '+(tutorialPlace===id?'solid '+(valid?'#bad7a7':'#e8a68d'):'dashed #c8b389')+'" data-action="tutorial-place" data-id="'+id+'" aria-pressed="'+(tutorialPlace===id)+'">'+scene(kind,{complete:valid&&tutorialPlace===id})+'<strong>'+label+'</strong></button>').join('')+'</div><p class="practice-feedback" aria-live="polite">'+esc(tutorialFeedback)+'</p><div class="impact-tags"><span>'+w('朝向 ','Orientation ')+Math.round(tutorialRotation*180/Math.PI)+'°</span>'+button('tutorial-rotate','↻ '+rotationStep(tutorialCard)+'° '+w('旋转练习预览','Rotate practice preview'))+'</div>';
   actions=button('tutorial-finish',w('确认练习位置，开始探索','Confirm practice placement and explore'),'','primary-button',valid?'':'disabled')+button('tutorial-step',w('换张练习牌','Try another practice card'),'1');
  }
  open(headings[step],content+'<div class="impact-tags"><span>'+w('练习 · 不扣预算','Practice · no budget spent')+'</span><span>'+w('正式时间暂停','Game time paused')+'</span></div><div class="modal-bottom">'+actions+button('tutorial-skip',w('跳过教程','Skip tutorial'))+'</div>',w('短互动教程','Short interactive tutorial'),false,{kind:'tutorial',step});
 }
 function feedbackCopy(event){const id=sceneKind(event.cardId),isStart=event.type==='start';if(isStart)return w('安排已经确认。准备或施工需要时间，回到社区可以观察进展。','Your arrangement is confirmed. Preparation or construction takes time. Return to the neighbourhood to watch it progress.');const map={cover:[w('“这次，我不用在那段露天路口停下来了。”','“This time I do not have to stop at the uncovered section.”')],mediate:[w('“先认识彼此的作息，安静时段就有了共同约定。”','“Now we understand each other’s routines and have agreed on quiet hours.”')],event:[w('“下回在食阁碰面，我们已经知道怎样打招呼。”','“Next time we meet at the food centre, we will know each other.”')],appeal:[w('“资料已经受理，下一步有了具体跟进。还不能保证豁免或成交。”','“The case has been received and there is a next step. An exemption or sale is still not guaranteed.”')],visits:[w('“现在知道可以联系谁，也有人定期来关心我们的近况。”','“Now we know whom to contact, with regular check-ins to see how we are doing.”')],ease:[w('“屋内和入口更安全了，屋外的通路还要分别留意。”','“Home and the entrance are safer. Outdoor routes still need their own attention.”')],keep:[w('“花园暂时保留，其他家庭的需要仍要继续安排。”','“The garden stays for now. Other households’ needs still need support.”')]};if(event.type==='worsen'){const i=state.issues.find(i=>i.id===event.issueId);return i?issueInfo(i).impact:w('等待已经影响了居民的日常。','Waiting is now affecting everyday life.');}return map[id]?.[0]||w('这次安排让日常有了变化。继续看看谁得到了支持，谁还需要帮助。','This arrangement changed everyday life. Keep watching who is supported and who still needs help.');}
 function showFeedback(event,replay=false){const c=card(event.cardId),i=state.issues.find(i=>i.id===event.issueId),title=event.type==='worsen'?w('等待带来了变化','Waiting has consequences'):event.type==='start'?w('安排开始了','Your action is underway'):event.type==='complete'?w('日常发生了变化','Everyday life has changed'):w('邻里有了新的约定','A new arrangement between neighbours');const kind=event.optionId||sceneKind(event.cardId)||i?.id||'help';open(title,'<div class="scene-and-dialogue">'+scene(kind,{complete:event.type==='complete'||event.type==='decision'})+'<div><div class="speaker">'+esc(c?cardText(c,'title'):i?tr(i.title):w('邻里反馈','Neighbourhood feedback'))+'</div><div class="speech-box"><p>'+esc(feedbackCopy(event))+'</p></div></div></div>'+changesMarkup(event.changes)+(event.type==='start'&&c?.duration?'<p class="library-description">◷ '+c.duration+' '+w('经营秒后完成；收益到完成时结算。','game seconds to complete; benefits arrive on completion.')+'</p>':'')+'<div class="modal-bottom">'+button(replay?'journal':'close',replay?w('返回社区记录','Back to the journal'):w('回到社区观察','Return and observe'),'','primary-button')+(feedbackQueue.length&&!replay?button('next-feedback',w('查看下一条反馈','Next feedback')):'')+'</div><p class="new-epoch">'+(replay?w('重看情境不会扣费或再次结算收益。','Replaying does not charge resources or grant benefits again.'):w('数值变化对应这一次安排；持续服务仍占用运营人手。','These changes belong to this action. Ongoing services keep staff assigned.'))+'</p>',replay?w('记录回看 · 不重复结算','Replay · no repeated rewards'):w('行动反馈 · 时间已暂停','Action feedback · time paused'),false,{kind:'feedback',eventId:event.id,replay});}
 function consumeEvents(){for(const event of state.events||[]){if(event.id<=lastSerial)continue;lastSerial=event.id;for(const id of ['budget','trust','staffUsed'])animateResource(id,event.changes?.[id]);root.HDBScene?.cue?.(event);if(event.type==='worsen'&&event.channel==='mail'){toast(w('有居民的来信等待较久，请打开邮箱查看。','A resident has been waiting. Please check your mailbox.'));continue;}feedbackQueue.push(event);}feedbackQueue=feedbackQueue.slice(-20);}
 function flushFeedback(){if(!inGame||blocked()||state.outcome||!feedbackQueue.length)return;showFeedback(feedbackQueue.shift());}
 function showJournal(){open(w('社区记录与行动回看','Journal and action replays'),'<h3>'+w('正在进行','Underway')+'</h3>'+(state.projects.length?state.projects.map(p=>'<div class="journal-row"><time>◷ '+Math.ceil(p.remaining)+'s</time><span>'+esc(cardText(card(p.cardId),'title'))+' · '+esc(p.plotId?plotText(plot(p.plotId),'name'):w('社区服务','Neighbourhood service'))+'</span></div>').join(''):'<p class="empty-copy">'+w('暂无进行中的安排。','No arrangements are underway.')+'</p>')+'<h3>'+w('行动情境 · 可以重看','Action scenes · replay anytime')+'</h3>'+(state.events||[]).slice().reverse().map(e=>'<div class="journal-row"><time>'+fmt(e.at)+'</time><span>'+esc(card(e.cardId)?cardText(card(e.cardId),'title'):tr(state.issues.find(i=>i.id===e.issueId)?.title||''))+' · '+({start:w('开始','Started'),complete:w('完成','Completed'),decision:w('回应','Responded'),worsen:w('等待变化','Waiting changed things')})[e.type]+'</span>'+button('replay',w('重看','Replay'),String(e.id),'replay-button')+'</div>').join('')+details(w('完整文字记录','Full written record'),state.history.map(h=>'<p>'+fmt(h.time)+' · '+esc(tr(h.text))+'</p>').join('')),w('每个安排都留下痕迹','Every arrangement leaves a trace'),true,{kind:'journal'});}
 function showSources(){const sources=[...new Map(D.cards.filter(c=>c.source?.url).map(c=>[c.source.url,c.source])).values()];open(w('现实对照与角色依据','Real-world context and character evidence'),'<p>'+w('政策方向有公开来源；居民、预算、工期、地块与效果数值为游戏设定。','Policy directions have public sources. Residents, budgets, times, sites and numerical effects are game assumptions.')+'</p>'+sources.map(s=>'<div class="source-entry"><strong>'+esc(tr(s.title))+'</strong><p>'+esc(tr(s.text))+'</p><a href="'+esc(s.url)+'" target="_blank" rel="noopener noreferrer">'+w('查看来源 ↗','View source ↗')+'</a></div>').join('')+(root.CM_COMMUNITY?'<div class="source-entry"><strong>'+w('社区人口与人物','Population and characters')+'</strong><p>'+esc(pair(root.CM_COMMUNITY.demographics.method))+'</p><p>'+esc(pair(root.CM_COMMUNITY.disclaimer))+'</p><a href="'+root.CM_COMMUNITY.demographics.sourceUrl+'" target="_blank" rel="noopener noreferrer">SingStat ↗</a></div>':''),w('资料与创作说明','Sources and design notes'),true,{kind:'sources'});}
 function help(){open(w('从观察开始，自己作决定','Observe first, then make your own decisions'),'<div class="scene-and-dialogue">'+scene('tutorial')+'<div><p>'+w('地图提示：你能观察到的公共处境。邮箱：居民主动写给你的私人需求。打开完整牌库寻找行动，再去合适的位置安排。','Map prompts show observable public situations. The mailbox holds personal requests. Explore the complete card library, then arrange actions in suitable places.')+'</p><p>'+w('阅读、练习和选址时暂停。回到地图继续，等待中的问题可能恶化。','Reading, practice and placement pause time. Back in the world, waiting issues can worsen.')+'</p></div></div><div class="modal-bottom">'+button('tutorial',w('重看互动教程','Replay the tutorial'),'','primary-button')+button('goals',w('看看三个目标','Explore the three goals'))+button('close',w('回到社区','Back to the neighbourhood'))+'</div>',w('玩法说明','How to play'),false,{kind:'help'});}
 function ending(){shownOutcome=true;feedbackQueue=[];save();const won=state.outcome==='win',m=E.metrics(state),completed=Object.keys(state.flags.completed).filter(id=>state.flags.completed[id]).map(card).filter(Boolean);open(won?w('楼下的日常，继续了。','Everyday life continues downstairs.'):w('社区需要重新安排支持。','The neighbourhood needs a fresh approach.'),scene(won?'help':'care',{complete:won})+'<p class="persona-intro">'+(won?w('三个目标已经同时稳定了一段时间。下面是这一局实际完成的安排。','All three goals remained stable together. These are the arrangements you actually completed.'):w('至少一项目标持续低于危险线。回看来信与行动，可以尝试另一条路径。','At least one goal remained below the danger line. Review messages and actions, then try another path.'))+'</p><div class="impact-tags"><span>'+goalName('stay')+' '+m.stay+'</span><span>'+goalName('social')+' '+m.social+'</span><span>'+goalName('comfort')+' '+m.comfort+'</span><span>'+fmt(state.time)+'</span></div><h3>'+w('这一局完成了什么','What you completed')+'</h3><div class="identity-tags">'+(completed.length?completed.map(c=>'<span>'+esc(cardText(c,'title'))+'</span>').join(''):w('尚未完成长期安排。','No lasting arrangements were completed.'))+'</div><h3>'+w('谁还需要支持','Who still needs support')+'</h3>'+Object.entries(state.groups).map(([id,v])=>'<p class="library-description">'+groupName(id)+' · '+status(v).word+'</p>').join('')+'<div class="modal-bottom">'+button('new-game',w('再经营一次','Try another game'),'','primary-button')+button('journal',w('回看决定','Review decisions'))+button('close',w('回到本局社区','Review this neighbourhood'))+'</div>',w('这一局的社区','Your neighbourhood this time'),false,{kind:'ending'});}
 function renderMailbox(){const mails=state.issues.filter(i=>i.channel==='mail'),unread=mails.filter(i=>!i.read).length,waiting=mails.filter(i=>i.status==='open'),oldest=Math.max(0,...waiting.map(i=>i.age));$('mailbox').innerHTML='<span class="mailbox-icon">✉</span><span>'+w('居民邮箱','Mailbox')+'<small style="display:block">'+(oldest>=40?w('有来信等你回应','A neighbour is waiting'):w('点击打开来信','Open to read letters'))+'</small></span><span class="mailbox-count">'+unread+'</span>';$('mailbox').classList.toggle('has-unread',unread>0);$('mailbox').setAttribute('aria-label',w('居民邮箱，未读','Resident mailbox, unread')+' '+unread);if(inGame&&unread>lastMailCount)toast(w('邮箱收到新来信，请点开查看。','A new letter arrived. Open the mailbox to read it.'));lastMailCount=unread;const warning=waiting.filter(i=>i.age>=40).map(i=>i.id+':'+i.stage).join('|');if(inGame&&warning&&warning!==lastPrivateWarning)toast(w('有来信已等待40秒；继续等待可能影响居民。','A letter has waited 40 seconds. Further waiting can affect residents.'));lastPrivateWarning=warning;}
 function renderFeed(){const worldIssues=state.issues.filter(i=>i.channel==='world'&&i.status!=='resolved');$('world-feed').innerHTML='<div class="dock-heading"><h2>'+w('正在发生 · 社区观察','Happening now · observations')+'</h2><span>'+worldIssues.length+'</span></div>'+(worldIssues.length?worldIssues.map(i=>'<button class="world-issue '+(i.stage||i.age>=40?'is-urgent':'')+'" data-action="issue" data-id="'+i.id+'"><span class="issue-symbol">'+(i.status==='pending'?'◷':i.stage?'!':'◇')+'</span><span><strong>'+esc(tr(i.title))+'</strong><small>'+(i.status==='pending'?w('正在跟进','In progress'):Math.floor(i.age)+'s · '+w('持续等待会有影响','Waiting has consequences'))+'</small><progress max="60" value="'+i.age%60+'"></progress></span></button>').join(''):'<p class="empty-copy">'+w('四处看看，新的情况会陆续出现。','Look around. More situations will unfold.')+'</p>')+(state.projects.length?'<div class="project-title">'+w('工程与准备中的服务','Works and services being prepared')+'</div>'+state.projects.map(p=>'<span class="project-mini">'+esc(cardText(card(p.cardId),'title'))+' · '+Math.ceil(p.remaining)+'s<progress max="'+p.total+'" value="'+(p.total-p.remaining)+'"></progress></span>').join(''):'');}
 function renderMetrics(){if(!metricsReady){metricsReady=true;$('metrics').innerHTML=['stay','social','comfort'].map(id=>'<button class="metric-row" data-action="goals" data-id="'+id+'" id="metric-'+id+'"><span id="metric-label-'+id+'"></span><strong id="metric-value-'+id+'"></strong><progress id="metric-progress-'+id+'" max="100"></progress></button>').join('');}const m=E.metrics(state);for(const id of Object.keys(m)){$('metric-label-'+id).textContent=goalName(id);$('metric-value-'+id).textContent=String(m[id]);$('metric-progress-'+id).value=m[id];}$('stability').textContent=state.danger>0?w('有目标低于危险线：','A goal is below danger: ')+Math.floor(state.danger)+' / 45s':state.hold>0?w('日常正在稳定：','Daily life is stabilising: ')+Math.floor(state.hold)+' / 60s':w('三项目标达标后，继续保持60秒。','Meet all three goals, then keep them stable for 60 seconds.');}
 function render(){localizeStatic();$('game').classList.toggle('is-placing',!!selecting);$('game').inert=!inGame||!!root.CM_FLOW?.isActive?.();renderResources();renderMetrics();renderFeed();renderMailbox();const neighbourKey=lang()+JSON.stringify(state.groups);if(neighbourKey!==lastNeighbours){lastNeighbours=neighbourKey;$('neighbours').innerHTML=D.residents.map(r=>{const st=status(state.groups[r.group]);return '<button class="neighbour-chip '+st.cls+'" data-action="resident" data-id="'+r.id+'" title="'+esc(tr(r.name))+' · '+st.word+'">'+portrait(r.id)+'<span>'+esc(tr(r.name))+'</span><i></i></button>';}).join('');}const handIds=[...recommendedCards(contextIssue),...D.cards.filter(c=>availability(c).ok).map(c=>c.id),...['cover','ramp','corner','visits','event']].filter((id,index,list)=>list.indexOf(id)===index).slice(0,5),handKey=lang()+handIds.join('|')+JSON.stringify(handIds.map(id=>availability(card(id)).ok));if(handKey!==lastHand){lastHand=handKey;$('hand-cards').innerHTML=handIds.map(id=>cardMarkup(card(id),recommendedCards(contextIssue).includes(id))).join('');}$('card-total').textContent=D.cards.length;const minutes=7*60+Math.floor(state.time*2);$('life-time').textContent=String(Math.floor(minutes/60)%24).padStart(2,'0')+':'+String(minutes%60).padStart(2,'0')+' · '+w('社区正在生活','Life in the neighbourhood');$('living-hint').textContent=selecting?w('描边位置可以查看；选址期间时间暂停。','Explore outlined places. Time is paused during placement.'):state.issues.some(i=>i.channel==='mail'&&!i.read)?w('邮箱有新来信；居民正在等你了解他们的情况。','New mail: a neighbour is waiting to tell you their situation.'):w('点地图上的情况、认识邻居，或打开完整牌库。','Explore map situations, meet neighbours or open the complete card library.');if(inGame&&!selecting&&!$('modal').open){const next=state.issues.find(i=>i.channel==='world'&&i.status==='open'&&!seenNotices.has(i.id+':'+i.stage));if(next){noticeId=next.id;seenNotices.add(next.id+':'+next.stage);setNotice('<span class="notice-kicker">'+w('社区里有新情况','Something is happening nearby')+'</span>'+button('dismiss-notice','×','','notice-close')+'<strong>'+esc(tr(next.title))+'</strong><p>'+esc(issueInfo(next).quote)+'</p>'+button('issue',w('去看看','Take a look'),next.id,'primary-button')+button('dismiss-notice',w('稍后','Later'),'','text-button'));}}if(selecting||$('modal').open)$('event-notice').hidden=true;else if(noticeId)$('event-notice').hidden=false;const worldOpts={selectedPlot,selectingCard:selecting,showLand:landVisible,paused:blocked(),language:lang(),simTime:state.time,issues:inGame?state.issues.filter(i=>i.channel==='world'&&i.status==='open').slice(0,3).map(i=>({id:i.id,title:i.title,anchor:({route:'route',noise:'students',land:'garden',petition:'void',ballot:'void'})[i.id],stage:i.stage})):[]};root.CM_SCENE?.sync?.(state,worldOpts);if(!$('world').hidden&&root.CM_WORLD){const key=JSON.stringify([state.plots,state.groups,state.flags,selecting,selectedPlot,lang()]);if(key!==lastWorld){lastWorld=key;$('world').innerHTML=root.CM_WORLD.render(state,worldOpts);root.CM_I18N?.localize?.($('world'));}}renderTime();}
 function enterCase(options={}){state=options.resume&&saved?E.migrate(saved):E.create();inGame=true;speed=1;userPaused=false;selecting=null;selectedPlot=null;feedbackQueue=[];lastSerial=state.eventSerial||0;shownOutcome=false;contextIssue=null;seenNotices.clear();noticeId=null;lastMailCount=state.issues.filter(i=>i.channel==='mail'&&!i.read).length;lastPrivateWarning='';lastTick=root.performance.now();lastHand='';lastNeighbours='';close();render();save();if(!state.flags.tutorialSeen)showTutorial();}
 function backToMap(){save();inGame=false;selecting=null;selectedPlot=null;feedbackQueue=[];root.HDBScene?.clearPreview?.();$('placement-panel').hidden=true;close();root.CM_FLOW?.showMap?.();render();}
 function restartPrompt(){open(w('重新接手社区？','Start the neighbourhood again?'),'<p>'+w('新开局会替代本局存档。你可以先在记录中回看已经作出的决定。','A new game replaces this save. You can first review the decisions in your journal.')+'</p><div class="modal-bottom">'+button('new-game',w('返回地图，重新开局','Return to map and start again'),'','primary-button')+button('close',w('继续这一局','Continue this game'))+'</div>',w('重新开局','Start again'),false,{kind:'restart'});}
 function setLanguage(value){root.CM_I18N?.setLanguage?.(value);render();refreshModal();}
 function refreshModal(){const current=modalView;if(!current||!$('modal').open)return;switch(current.kind){case'card':showCard(current.id);break;case'issue':showIssue(current.id);break;case'ideas':showIdeas(current.id);break;case'library':showLibrary();break;case'inbox':showInbox();break;case'resident':showResident(current.id);break;case'residents':showResidents();break;case'goals':showGoals(current.id);break;case'tutorial':showTutorial(current.step);break;case'journal':showJournal();break;case'sources':showSources();break;case'help':help();break;case'mediation':showMediation();break;case'feedback':{const event=state.events.find(e=>e.id===current.eventId);if(event)showFeedback(event,current.replay);break;}case'ending':ending();break;case'plot':showPlot(current.id);break;case'restart':restartPrompt();break;}if(selecting&&selectedPlot)renderPlacement();}
 doc.addEventListener('click',event=>{const target=event.target.closest?.('[data-action]');if(target&&!target.disabled){const {action,id}=target.dataset;switch(action){case'close':close();break;case'card':showCard(id);break;case'use-card':useCard(id);break;case'library':showLibrary();break;case'inbox':showInbox();break;case'issue':showIssue(id);break;case'ideas':showIdeas(id);break;case'resident':showResident(id);break;case'residents':showResidents();break;case'goals':practice=false;showGoals(id);break;case'rule-tab':practice=false;showGoals(id);break;case'practice':practice=!practice;showGoals(id);break;case'tutorial':showTutorial();break;case'tutorial-step':showTutorial(Number(id));break;case'tutorial-pick':tutorialCard=id;tutorialPlace=null;tutorialRotation=0;tutorialFeedback='';showTutorial(2);break;case'tutorial-place':tutorialPlace=id;tutorialFeedback=id===({cover:'route',ramp:'crossing',ease:'home'})[tutorialCard]?w('这里适合这张牌。改善会发生在对应位置。','This place suits the card. The change happens at the relevant place.'):w('这里不适合这张牌，换一处描边位置试试。','This place does not suit the card. Try another outlined place.');showTutorial(2);break;case'tutorial-rotate':tutorialRotation=nextRotation(tutorialCard,tutorialRotation);showTutorial(2);break;case'tutorial-finish':if(tutorialPlace!==({cover:'route',ramp:'crossing',ease:'home'})[tutorialCard])return;case'tutorial-skip':state.flags.tutorialSeen=true;save();close();break;case'help':help();break;case'journal':showJournal();break;case'sources':showSources();break;case'restart':restartPrompt();break;case'new-game':case'case-map':backToMap();return;case'dismiss-notice':noticeId=null;setNotice('');break;case'toggle-panels':$('game').classList.toggle('ui-collapsed');break;case'category':filters.category=id;showLibrary();break;case'goal-filter':filters.goal=id;showLibrary();break;case'available-filter':filters.available=!filters.available;showLibrary();break;case'quiet-slot':quietSlot=id;showMediation();break;case'confirm-mediate':if(execute('action-mediate')){state.flags.quietMeetingTime=quietSlot;save();}break;case'cancel-select':selecting=null;selectedPlot=null;root.HDBScene?.clearPreview?.();$('placement-panel').hidden=true;break;case'rotate-placement':placement.rotation=nextRotation(selecting,placement.rotation);renderPlacement();root.HDBScene?.previewPlacement?.(selectedPlot,selecting,placement);break;case'confirm-placement':if(selecting&&selectedPlot)execute(selecting,selectedPlot,placement);break;case'build':if(selecting)execute(selecting,id,placement);break;case'replay':{const e=state.events.find(e=>e.id===Number(id));if(e)showFeedback(e,true);break;}case'next-feedback':close();flushFeedback();break;}render();return;}const hit=event.target.closest?.('[data-resident],[data-plot]');if(hit?.dataset.resident)showResident(hit.dataset.resident);else if(hit?.dataset.plot)showPlot(hit.dataset.plot);});
 doc.addEventListener('input',event=>{const target=event.target;if(target.id==='library-search'){filters.search=target.value;renderLibraryGrid();}if(target.id==='placement-x'||target.id==='placement-z'){placement[target.id==='placement-x'?'x':'z']=Number(target.value);root.HDBScene?.previewPlacement?.(selectedPlot,selecting,placement);}});
 $('pause').onclick=()=>{userPaused=!userPaused;lastTick=root.performance.now();render();};$('speed').onclick=()=>{speed=speed===1?2:speed===2?3:1;renderTime();};$('language-toggle').onclick=()=>setLanguage(lang()==='en'?'zh':'en');
 $('overview-button').onclick=()=>root.HDBScene?.showNeighborhood?.();$('rotate-left').onclick=()=>root.HDBScene?.rotate?.(-1);$('rotate-right').onclick=()=>root.HDBScene?.rotate?.(1);$('zoom-in').onclick=()=>root.HDBScene?.zoom?.(.15);$('zoom-out').onclick=()=>root.HDBScene?.zoom?.(-.15);$('reset-camera').onclick=()=>root.HDBScene?.reset?.();$('land-toggle').onclick=()=>{landVisible=!landVisible;$('land-toggle').setAttribute('aria-pressed',String(landVisible));render();};
 $('modal').addEventListener('close',()=>{modalView=null;lastTick=root.performance.now();renderTime();});doc.addEventListener('visibilitychange',()=>{lastTick=root.performance.now();save();renderTime();});root.addEventListener?.('beforeunload',save);root.addEventListener?.('localechange',()=>{lastHand='';lastNeighbours='';render();refreshModal();});root.addEventListener?.('keydown',event=>{if(event.key==='Escape'&&selecting&&!$('modal').open){selecting=null;selectedPlot=null;root.HDBScene?.clearPreview?.();$('placement-panel').hidden=true;render();}});
 root.setInterval(()=>{const now=root.performance.now(),dt=Math.min(.5,Math.max(0,(now-lastTick)/1000));lastTick=now;if(!blocked()){E.tick(state,dt*speed);saveClock+=dt;if(saveClock>=5){saveClock=0;save();}}consumeEvents();if(now-lastPaint>=650){lastPaint=now;render();}if(state.outcome&&!shownOutcome){render();ending();}else flushFeedback();},200);
 root.CM_APP={getState:()=>state,getSelection:()=>selecting,isPlaying:()=>inGame,getPaused:blocked,enterCase,setLanguage,showLibrary,showResidents,showResident,showIssue,showPlot,showCard,showGoals,showInbox,showTutorial,showJournal,showSources,render};
 render();if(root.CM_FLOW)root.CM_FLOW.start({onEnter:enterCase,hasSave:()=>!!saved&&!saved.outcome});else enterCase();
})(typeof window!=='undefined'?window:globalThis);
